-- Популярные Android модели (smarfony.ru) — Samsung, Xiaomi, Redmi, Honor, Realme, Tecno, Infinix, Poco
ON CONFLICT (brand, model) DO UPDATE SET
  display = EXCLUDED.display, ram = EXCLUDED.ram, battery = EXCLUDED.battery,
  processor = EXCLUDED.processor, camera = EXCLUDED.camera, short_text = EXCLUDED.short_text,
  source_url = EXCLUDED.source_url, updated_at = NOW();